import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;

public class OnlineStockSpanTest {

    @Before
    public void setup() {
        // Do nothing as per the requirements
    }

    @Test
    public void next_WithZeroPrice_ReturnsOne() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        assertEquals(1, onlineStockSpan.next(0));
    }

    @Test
    public void next_WithNegativePrice_ReturnsOne() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        assertEquals(1, onlineStockSpan.next(-100));
    }

    @Test
    public void next_DifferentPositivePrices_ReturnsDifferentIntegers() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10, 20, 30, 40};
        for (int price : prices) {
            assertEquals(price + 1, onlineStockSpan.next(price));
        }
    }

    @Test
    public void next_DifferentNegativePrices_ReturnsDifferentIntegers() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {-10, -20, -30};
        for (int price : prices) {
            assertEquals(price + 1, onlineStockSpan.next(price));
        }
    }

    @Test
    public void calculateSpans_EmptyArray_ReturnsEmptyArray() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[0]);
        assertEquals(0, result.length);
    }

    @Test
    public void calculateSpans_SingleElementArray_ReturnsCorrectSpan() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10};
        int[] result = onlineStockSpan.calculateSpans(prices);
        assertEquals(1, result[0]);
    }

    @Test
    public void calculateSpans_MultiElementArray_ReturnsCorrectSpans() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10, 20, 30};
        int[] result = onlineStockSpan.calculateSpans(prices);
        assertEquals(2, result[0]);
        assertEquals(1, result[1]);
    }

    @Test
    public void calculateSpans_MultiElementArray_ReturnsCorrectSpansAndCumulativeSum() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10, 20, 30};
        int[] result = onlineStockSpan.calculateSpans(prices);
        assertEquals(3, result[0]);
        assertEquals(4, result[1]);
        assertEquals(5, result[2]);
    }
}
